Output7[Better Approach - 2] Using Tabulation - O(n^2) Time and O(n^2) SpaceThe above approach can be implemented using tabulation to minimize the auxiliary space required for recursive stack. We define a 2D table dp, where dp[i][j] stores the length of the longest palindromic subsequence within the substring s[i...j].We iteratively fill the table from smaller substrings to larger ones. If the characters at both ends match, we add 2 to the result from the subsequence s[i+1...j-1]. If they don't match, we take the maximum from excluding either the character at the start or the end.The result for the entire string is stored in dp[0][n-1].
            C++

    #include <iostream>
#include <vector>
#include <string> 
using namespace std;


int longestPalinSubseq(string& s) {
    int n = s.length();

    // Create a DP table
    vector<vector<int>> dp(n, vector<int>(n));

    // Build the DP table for all the substrings
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i; j < n; j++) { 

            // If there is only one character
            if(i == j){
                dp[i][j] = 1;
                continue;
            }

            // If characters at position i and j are the same
            if (s[i] == s[j]) {
                if(i + 1 == j) dp[i][j] = 2;
                else dp[i][j] = dp[i + 1][j - 1] + 2;
            } 
            else {

                // Otherwise, take the maximum length
                // from either excluding i or j
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
    }

    // The final answer is stored in dp[0][n-1]
    return dp[0][n - 1];
}

int main() {
    string s = "bbabcbcab";
    cout << longestPalinSubseq(s);
    return 0;
}


